import React, { useState, useEffect } from 'react';
import { taskAPI, budgetAPI } from '../utils/api';
import { useAuthStore } from '../store/authStore';

interface Task {
  id: number;
  title: string;
  description: string;
  priority: string;
  status: string;
  due_date: string;
  assigned_to: number;
}

interface Budget {
  category: string;
  monthly_limit: number;
  spent_amount: number;
}

const Dashboard: React.FC = () => {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [budgets, setBudgets] = useState<Budget[]>([]);
  const [loading, setLoading] = useState(true);
  const { userId } = useAuthStore();

  useEffect(() => {
    loadDashboardData();
  }, []);

  const loadDashboardData = async () => {
    try {
      const [tasksRes, budgetRes] = await Promise.all([
        taskAPI.getAll({ limit: 5 }),
        budgetAPI.get()
      ]);
      setTasks(tasksRes.data);
      setBudgets(budgetRes.data);
    } catch (error) {
      console.error('Error loading dashboard:', error);
    } finally {
      setLoading(false);
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'high': return '#ff4757';
      case 'medium': return '#ffa502';
      case 'low': return '#2ed573';
      default: return '#747d8c';
    }
  };

  if (loading) {
    return (
      <div style={styles.loading}>
        <div style={styles.spinner}></div>
        <p>Yükleniyor...</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <h1 style={styles.title}>Aile Panosu</h1>
        <p style={styles.subtitle}>Günlük görevler ve bütçe durumu</p>
      </header>

      <div style={styles.grid}>
        {/* Recent Tasks */}
        <div style={styles.card}>
          <h2 style={styles.cardTitle}>Son Görevler</h2>
          {tasks.length === 0 ? (
            <p style={styles.emptyState}>Henüz görev yok</p>
          ) : (
            <div style={styles.taskList}>
              {tasks.slice(0, 5).map((task) => (
                <div key={task.id} style={styles.taskItem}>
                  <div style={styles.taskHeader}>
                    <h3 style={styles.taskTitle}>{task.title}</h3>
                    <span 
                      style={{
                        ...styles.priorityBadge,
                        backgroundColor: getPriorityColor(task.priority)
                      }}
                    >
                      {task.priority}
                    </span>
                  </div>
                  <p style={styles.taskDesc}>{task.description}</p>
                  <div style={styles.taskMeta}>
                    <span style={styles.taskStatus}>{task.status}</span>
                    {task.due_date && (
                      <span style={styles.taskDate}>
                        {new Date(task.due_date).toLocaleDateString('tr-TR')}
                      </span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Budget Overview */}
        <div style={styles.card}>
          <h2 style={styles.cardTitle}>Bütçe Durumu</h2>
          {budgets.length === 0 ? (
            <p style={styles.emptyState}>Bütçe bilgisi yok</p>
          ) : (
            <div style={styles.budgetList}>
              {budgets.map((budget, index) => {
                const percentage = (budget.spent_amount / budget.monthly_limit) * 100;
                return (
                  <div key={index} style={styles.budgetItem}>
                    <div style={styles.budgetHeader}>
                      <span style={styles.budgetCategory}>{budget.category}</span>
                      <span style={styles.budgetAmount}>
                        ₺{budget.spent_amount} / ₺{budget.monthly_limit}
                      </span>
                    </div>
                    <div style={styles.progressBar}>
                      <div 
                        style={{
                          ...styles.progressFill,
                          width: `${Math.min(percentage, 100)}%`,
                          backgroundColor: percentage > 90 ? '#ff4757' : percentage > 70 ? '#ffa502' : '#2ed573'
                        }}
                      ></div>
                    </div>
                    <span style={styles.budgetPercentage}>{percentage.toFixed(1)}%</span>
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* Quick Stats */}
        <div style={styles.card}>
          <h2 style={styles.cardTitle}>Hızlı İstatistikler</h2>
          <div style={styles.statsGrid}>
            <div style={styles.statItem}>
              <div style={styles.statNumber}>{tasks.filter(t => t.status === 'pending').length}</div>
              <div style={styles.statLabel}>Bekleyen Görevler</div>
            </div>
            <div style={styles.statItem}>
              <div style={styles.statNumber}>{tasks.filter(t => t.status === 'completed').length}</div>
              <div style={styles.statLabel}>Tamamlanan</div>
            </div>
            <div style={styles.statItem}>
              <div style={styles.statNumber}>{tasks.filter(t => t.assigned_to === userId).length}</div>
              <div style={styles.statLabel}>Benim Görevlerim</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const styles = {
  container: {
    padding: '24px',
    maxWidth: '1200px',
    margin: '0 auto',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  },
  loading: {
    display: 'flex',
    flexDirection: 'column' as const,
    alignItems: 'center',
    justifyContent: 'center',
    height: '400px',
    color: '#666',
  },
  spinner: {
    width: '40px',
    height: '40px',
    border: '4px solid #f3f3f3',
    borderTop: '4px solid #007bff',
    borderRadius: '50%',
    animation: 'spin 1s linear infinite',
    marginBottom: '16px',
  },
  header: {
    marginBottom: '32px',
    textAlign: 'center' as const,
  },
  title: {
    fontSize: '32px',
    fontWeight: '700',
    color: '#2c3e50',
    margin: '0 0 8px 0',
  },
  subtitle: {
    fontSize: '16px',
    color: '#7f8c8d',
    margin: 0,
  },
  grid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(350px, 1fr))',
    gap: '24px',
  },
  card: {
    backgroundColor: '#fff',
    borderRadius: '12px',
    padding: '24px',
    boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
    border: '1px solid #e9ecef',
  },
  cardTitle: {
    fontSize: '20px',
    fontWeight: '600',
    color: '#2c3e50',
    margin: '0 0 20px 0',
  },
  emptyState: {
    textAlign: 'center' as const,
    color: '#95a5a6',
    fontStyle: 'italic',
    padding: '40px 20px',
  },
  taskList: {
    display: 'flex',
    flexDirection: 'column' as const,
    gap: '16px',
  },
  taskItem: {
    padding: '16px',
    backgroundColor: '#f8f9fa',
    borderRadius: '8px',
    border: '1px solid #e9ecef',
  },
  taskHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '8px',
  },
  taskTitle: {
    fontSize: '16px',
    fontWeight: '600',
    color: '#2c3e50',
    margin: 0,
  },
  priorityBadge: {
    padding: '4px 8px',
    borderRadius: '12px',
    fontSize: '12px',
    fontWeight: '500',
    color: '#fff',
    textTransform: 'uppercase' as const,
  },
  taskDesc: {
    fontSize: '14px',
    color: '#6c757d',
    margin: '0 0 12px 0',
    lineHeight: '1.4',
  },
  taskMeta: {
    display: 'flex',
    justifyContent: 'space-between',
    fontSize: '12px',
    color: '#95a5a6',
  },
  taskStatus: {
    textTransform: 'capitalize' as const,
  },
  taskDate: {},
  budgetList: {
    display: 'flex',
    flexDirection: 'column' as const,
    gap: '16px',
  },
  budgetItem: {
    padding: '16px',
    backgroundColor: '#f8f9fa',
    borderRadius: '8px',
  },
  budgetHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    marginBottom: '8px',
  },
  budgetCategory: {
    fontWeight: '600',
    color: '#2c3e50',
    textTransform: 'capitalize' as const,
  },
  budgetAmount: {
    fontSize: '14px',
    color: '#6c757d',
  },
  progressBar: {
    width: '100%',
    height: '8px',
    backgroundColor: '#e9ecef',
    borderRadius: '4px',
    overflow: 'hidden',
    marginBottom: '8px',
  },
  progressFill: {
    height: '100%',
    transition: 'width 0.3s ease',
  },
  budgetPercentage: {
    fontSize: '12px',
    color: '#6c757d',
  },
  statsGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(3, 1fr)',
    gap: '16px',
  },
  statItem: {
    textAlign: 'center' as const,
    padding: '16px',
    backgroundColor: '#f8f9fa',
    borderRadius: '8px',
  },
  statNumber: {
    fontSize: '24px',
    fontWeight: '700',
    color: '#007bff',
    marginBottom: '4px',
  },
  statLabel: {
    fontSize: '12px',
    color: '#6c757d',
    textTransform: 'uppercase' as const,
    letterSpacing: '0.5px',
  },
};

export default Dashboard;
